changeSet.sql:
CREATE OR REPLACE FUNCTION bng.reject_login_audit_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION
        'bng.login_audit is append-only; % is not permitted', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER login_audit_reject_row_mutation
    BEFORE UPDATE OR DELETE ON bng.login_audit
    FOR EACH ROW
    EXECUTE FUNCTION bng.reject_login_audit_mutation();

CREATE TRIGGER login_audit_reject_truncate
    BEFORE TRUNCATE ON bng.login_audit
    FOR EACH STATEMENT
    EXECUTE FUNCTION bng.reject_login_audit_mutation();

changeSet.rollback:
DROP TRIGGER IF EXISTS login_audit_reject_truncate ON bng.login_audit;
DROP TRIGGER IF EXISTS login_audit_reject_row_mutation ON bng.login_audit;
DROP FUNCTION IF EXISTS bng.reject_login_audit_mutation();
